(self.webpackChunkvuepress_blog=self.webpackChunkvuepress_blog||[]).push([[3861],{3280:(n,s,a)=>{"use strict";a.r(s),a.d(s,{data:()=>p});const p={key:"v-759f3798",path:"/pages/node/usefulTips/",title:"",lang:"zh-CN",frontmatter:{},excerpt:"",headers:[{level:3,title:"EventEmitter",slug:"eventemitter",children:[]},{level:3,title:"ReferenceError: __dirname is not defined",slug:"referenceerror-dirname-is-not-defined",children:[]},{level:3,title:"捕获 SIGINT 信号",slug:"捕获-sigint-信号",children:[]},{level:3,title:"node --inspect",slug:"node-inspect",children:[]},{level:3,title:"node 服务心跳机制",slug:"node-服务心跳机制",children:[]}],filePathRelative:"pages/node/usefulTips/README.md",git:{updatedTime:1752500195e3,contributors:[{name:"COOKIES-LGL",email:"1344714332@qq.com",commits:6}]}}},730:(n,s,a)=>{"use strict";a.r(s),a.d(s,{default:()=>t});const p=(0,a(6252).uE)('<h3 id="eventemitter"><a class="header-anchor" href="#eventemitter">#</a> EventEmitter</h3><div class="language-javascript ext-js line-numbers-mode"><pre class="language-javascript"><code><span class="token keyword">const</span> <span class="token punctuation">{</span> EventEmitter <span class="token punctuation">}</span> <span class="token operator">=</span> <span class="token function">require</span><span class="token punctuation">(</span><span class="token string">&quot;events&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>\n<span class="token keyword">const</span> emitter <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">EventEmitter</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>\n\nemitter<span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token string">&quot;doSomething&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token parameter">arg1<span class="token punctuation">,</span> arg2</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>\n  console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token template-string"><span class="token template-punctuation string">`</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">${</span>arg1<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string"> </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">${</span>arg2<span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">`</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span>\n<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>\n\nemitter<span class="token punctuation">.</span><span class="token function">emit</span><span class="token punctuation">(</span><span class="token string">&quot;doSomething&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;Hello&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;World&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// &#39;Hello World&#39;</span>\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="referenceerror-dirname-is-not-defined"><a class="header-anchor" href="#referenceerror-dirname-is-not-defined">#</a> ReferenceError: __dirname is not defined</h3><p>原因，NodeJS 支持通过 ESM 方式导入模块 package.json 加了以下配置</p><blockquote><p>&quot;type&quot;: &quot;module&quot;,</p></blockquote><p>使用下面的替代</p><div class="language-javascript ext-js line-numbers-mode"><pre class="language-javascript"><code><span class="token keyword">import</span> <span class="token punctuation">{</span> fileURLToPath <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&quot;url&quot;</span><span class="token punctuation">;</span>\n<span class="token keyword">import</span> <span class="token punctuation">{</span> dirname <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&quot;path&quot;</span><span class="token punctuation">;</span>\n<span class="token keyword">const</span> __filename <span class="token operator">=</span> <span class="token function">fileURLToPath</span><span class="token punctuation">(</span><span class="token keyword">import</span><span class="token punctuation">.</span>meta<span class="token punctuation">.</span>url<span class="token punctuation">)</span><span class="token punctuation">;</span>\n<span class="token keyword">const</span> __dirname <span class="token operator">=</span> <span class="token function">dirname</span><span class="token punctuation">(</span>__filename<span class="token punctuation">)</span><span class="token punctuation">;</span>\nconsole<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>__filename<span class="token punctuation">)</span><span class="token punctuation">;</span>\nconsole<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>__dirname<span class="token punctuation">)</span><span class="token punctuation">;</span>\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="捕获-sigint-信号"><a class="header-anchor" href="#捕获-sigint-信号">#</a> 捕获 SIGINT 信号</h3><div class="language-javascript ext-js line-numbers-mode"><pre class="language-javascript"><code>process<span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token string">&quot;SIGINT&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>\n  console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;捕获到SIGINT信号，执行清理工作...&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>\n  <span class="token comment">// 在这里执行清理工作，例如关闭数据库连接、保存数据等</span>\n  process<span class="token punctuation">.</span><span class="token function">exit</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>\n<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="node-inspect"><a class="header-anchor" href="#node-inspect">#</a> node --inspect</h3><p>node --inspect 是一个用于启动 Node.js 应用程序并同时开启远程调试功能的命令行选项</p><h3 id="node-服务心跳机制"><a class="header-anchor" href="#node-服务心跳机制">#</a> node 服务心跳机制</h3><p>‌Node 服务部署心跳请求的核心原因 ‌ 心跳机制是分布式系统与长连接场景中的关键设计，Node 服务部署心跳请求主要基于以下核心需求：</p><p>‌ 一、维持长连接活跃性 ‌ ‌ 防止网络设备中断连接 ‌</p><p>在 TCP 长连接中，若长时间无数据传输，路由器、防火墙等中间设备可能主动关闭连接。通过 ‌ 周期性发送心跳包 ‌（如 WebSocket 中的 PING/PONG），可告知网络设备连接仍在使用，避免被误判为闲置 。 ‌ 规避 NAT 超时问题 ‌</p><p>在 NAT 网络环境下，客户端与服务端的映射表项会因超时被删除。心跳包可刷新 NAT 映射，维持连接可路由性。 ‌ 二、实时检测连接与节点状态 ‌ ‌ 快速发现异常断连 ‌</p><p>若客户端或服务端因网络波动、进程崩溃等原因断连，心跳机制通过 ‌ 超时未响应 ‌（如 Node.js WebSocket 服务设定 1 秒超时）可快速触发重连或容错处理。 ‌ 分布式系统的节点健康监控 ‌</p><p>在微服务架构中（如 Nacos 注册中心），Node 服务通过心跳向中心上报存活状态。若中心未收到心跳，则判定节点故障并剔除，避免请求路由至不可用节点。 ‌ 三、资源管理与负载均衡优化 ‌ ‌ 释放无效连接资源 ‌</p><p>Node 服务需管理大量并发连接。通过心跳检测“僵尸连接”（如客户端异常退出未主动关闭），可及时释放 Socket、内存等资源，防止泄漏。 ‌ 动态调整服务负载 ‌</p><p>心跳包可携带节点负载信息（如 CPU、内存使用率），供负载均衡器决策。例如 Hadoop 的 NodeManager 通过心跳向 ResourceManager 上报资源状态，实现任务调度优化。 ‌ 四、容错与高可用保障 ‌ ‌ 自动重连机制 ‌</p><p>心跳检测到断连后，Node 服务可自动触发重连逻辑（如 WebSocket 客户端重连），减少人工干预，提升系统鲁棒性。 ‌ 故障转移与冗余备份 ‌</p><p>在集群部署中，若主节点心跳丢失，备用节点可快速接管服务，避免单点故障导致服务中断</p><p><strong>WebSocket 服务端心跳示例</strong></p><div class="language-javascript ext-js line-numbers-mode"><pre class="language-javascript"><code><span class="token keyword">const</span> WebSocket <span class="token operator">=</span> <span class="token function">require</span><span class="token punctuation">(</span><span class="token string">&quot;ws&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>\n<span class="token keyword">const</span> wss <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">WebSocket<span class="token punctuation">.</span>Server</span><span class="token punctuation">(</span><span class="token punctuation">{</span> port<span class="token operator">:</span> <span class="token number">8080</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>\n\nwss<span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token string">&quot;connection&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token parameter">ws</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>\n  <span class="token comment">// 定时发送心跳包</span>\n  <span class="token keyword">const</span> heartbeatInterval <span class="token operator">=</span> <span class="token function">setInterval</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>\n    <span class="token keyword">if</span> <span class="token punctuation">(</span>ws<span class="token punctuation">.</span>readyState <span class="token operator">===</span> WebSocket<span class="token punctuation">.</span><span class="token constant">OPEN</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>\n      ws<span class="token punctuation">.</span><span class="token function">ping</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 发送 PING 帧</span>\n    <span class="token punctuation">}</span>\n  <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token number">30000</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 30 秒一次</span>\n\n  <span class="token comment">// 监听 PONG 响应</span>\n  ws<span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token string">&quot;pong&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>\n    ws<span class="token punctuation">.</span>isAlive <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">;</span> <span class="token comment">// 标记连接活跃</span>\n  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>\n\n  <span class="token comment">// 检测超时</span>\n  <span class="token keyword">const</span> checkAlive <span class="token operator">=</span> <span class="token function">setInterval</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>\n    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>ws<span class="token punctuation">.</span>isAlive<span class="token punctuation">)</span> <span class="token punctuation">{</span>\n      ws<span class="token punctuation">.</span><span class="token function">terminate</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 超时未响应则关闭连接</span>\n      <span class="token function">clearInterval</span><span class="token punctuation">(</span>heartbeatInterval<span class="token punctuation">)</span><span class="token punctuation">;</span>\n      <span class="token function">clearInterval</span><span class="token punctuation">(</span>checkAlive<span class="token punctuation">)</span><span class="token punctuation">;</span>\n    <span class="token punctuation">}</span>\n    ws<span class="token punctuation">.</span>isAlive <span class="token operator">=</span> <span class="token boolean">false</span><span class="token punctuation">;</span> <span class="token comment">// 重置状态等待下一次 PONG</span>\n  <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token number">45000</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 超时设为 45 秒（略大于心跳间隔）</span>\n<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br></div></div><h4 id="promisify"><a class="header-anchor" href="#promisify">#</a> promisify</h4><p>promisify 是 Node.js util 模块提供的工具函数，用于将遵循 Node.js 回调风格（即 (err, value) =&gt; {}）的异步函数转换为返回 Promise 的函数。</p>',26),t={render:function(n,s){return p}}}}]);